public interface IModelRouter
{
    Task<string> RouteAsync(ModelRoutingContext context);
}

public record ModelRoutingContext(
    string Task,
    int EstimatedTokenCount,
    bool RequiresReasoning,
    bool RequiresMultimodal,
    Dictionary<string, object> Metadata
);

public class ModelRouter : IModelRouter
{
    private readonly IModelProvider _fastModel;  // GPT-3.5-turbo
    private readonly IModelProvider _reasoningModel;  // GPT-4
    private readonly IModelProvider _multimodalModel;  // GPT-4-Vision

    public async Task<string> RouteAsync(ModelRoutingContext context)
    {
        // Route based on requirements
        if (context.RequiresMultimodal)
        {
            return _multimodalModel.ModelId;
        }

        if (context.RequiresReasoning || context.EstimatedTokenCount > 2000)
        {
            return _reasoningModel.ModelId;
        }

        // Cost-based routing for simple tasks
        if (context.EstimatedTokenCount < 500 && !context.RequiresReasoning)
        {
            return _fastModel.ModelId;
        }

        // Default to reasoning model for balance
        return _reasoningModel.ModelId;
    }
}

// Usage
public class AIClient
{
    private readonly IModelRouter _router;
    private readonly Dictionary<string, IModelProvider> _providers;

    public async Task<string> CompleteAsync(string prompt, bool requiresReasoning = false)
    {
        var tokenCount = EstimateTokens(prompt);
        var context = new ModelRoutingContext(
            Task: "completion",
            EstimatedTokenCount: tokenCount,
            RequiresReasoning: requiresReasoning,
            RequiresMultimodal: false,
            Metadata: new()
        );

        var modelId = await _router.RouteAsync(context);
        var provider = _providers[modelId];

        return await provider.CompleteAsync(prompt);
    }
}
